// App Router async server component pattern - fetch on request
export default async function UserDashboard() {
  // Fetch user preferences - no caching for request-time data
  try {
    const res = await fetch('http://localhost:3000/api/user/preferences', {
      cache: 'no-store', // Ensure fresh data on every request
    });

    if (!res.ok) {
      throw new Error('Failed to fetch user preferences');
    }

    const preferences = await res.json();

    return (
      <div>
        <h2>User Dashboard</h2>
        <p>User preferences: {JSON.stringify(preferences)}</p>
      </div>
    );
  } catch (error) {
    console.error('Error fetching user preferences:', error);
    return (
      <div>
        <h2>User Dashboard</h2>
        <p>Failed to load user preferences.</p>
      </div>
    );
  }
}

